const clips = $('Buscar Clips Prontos').all();
const hojeResult = $('Publicados Hoje').first().json;
const publicadosHoje = hojeResult.total_hoje || 0;

if (!clips || clips.length === 0) {
  return [{
    json: {
      shouldNotify: true,
      message: `⚠️ *Aviso — 18h BRT*\n\nNenhum clipe pronto para publicar hoje.\n\nPublicados hoje: ${publicadosHoje}\n\nO pipeline está processando vídeos. Verifique:\n\`docker logs clip-processor --tail 20\``
    }
  }];
}

const hora = new Date().toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });

let msg = `🎬 *Fila para esta noite — ${hora} BRT*\n`;
msg += `Publicados hoje: ${publicadosHoje} | Na fila: ${clips.length}\n\n`;

clips.slice(0, 5).forEach((c, i) => {
  const d = c.json;
  const duracaoMin = d.duracao_s >= 60 ? `${Math.round(d.duracao_s/60)}min` : `${d.duracao_s}s ⚡Short`;
  const star = d.score >= 9 ? '⭐' : d.score >= 7 ? '🔥' : '';
  msg += `*${i+1}.* [ID:${d.id}] ${star} Score ${d.score}/10\n`;
  msg += `   ${duracaoMin} · ${d.canal}\n`;
  msg += `   ${d.titulo}\n\n`;
});

if (clips.length > 0) {
  const melhor = clips[0].json;
  msg += `💡 *Sugestão de publicação:* Use o ID ${melhor.id} (score mais alto)\n`;
  msg += `\`./manual-workflow/mark-published.sh ${melhor.id} <YT_VIDEO_ID>\``;
}

return [{ json: { shouldNotify: true, message: msg, clipsCount: clips.length } }];
